// Extract structured failure details from error context
const errorData = $input.first().json;

const failedWorkflow = errorData.workflow ? errorData.workflow.name : "Unknown Workflow";
const executionId = errorData.execution ? errorData.execution.id : "unknown_exec";
const errorMessage = errorData.execution && errorData.execution.error ? errorData.execution.error.message : (errorData.message || "Unspecified automation fault.");

return [{
  json: {
    workflow_name: failedWorkflow,
    execution_id: executionId,
    trigger_event: "workflow_failure",
    status: "failed",
    error_message: errorMessage,
    timestamp: new Date().toISOString(),
    retry_recommended: true,
    retry_endpoint: `${$env.FASTAPI_BACKEND_URL || 'http://backend:8000'}/api/v1/webhooks/n8n-callback`
  }
}];

